import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { createApp } from '../../src/app.js';

describe('Users API', () => {
  let app: ReturnType<typeof createApp>;

  beforeEach(() => {
    app = createApp();
  });

  describe('POST /users', () => {
    it('should create a user with email and name', async () => {
      const res = await request(app)
        .post('/users')
        .send({ email: 'john@example.com', name: 'John Doe' });

      expect(res.status).toBe(201);
      expect(res.body).toHaveProperty('id');
      expect(res.body.email).toBe('john@example.com');
      expect(res.body.name).toBe('John Doe');
      expect(res.body).toHaveProperty('createdAt');
    });

    it('should reject invalid email', async () => {
      const res = await request(app)
        .post('/users')
        .send({ email: 'not-an-email', name: 'John Doe' });

      expect(res.status).toBe(422);
      expect(res.body.type).toContain('validation-problem');
    });

    it('should reject name with length 0', async () => {
      const res = await request(app)
        .post('/users')
        .send({ email: 'john@example.com', name: '' });

      expect(res.status).toBe(422);
    });

    it('should reject name with length > 100', async () => {
      const res = await request(app)
        .post('/users')
        .send({ email: 'john@example.com', name: 'a'.repeat(101) });

      expect(res.status).toBe(422);
    });

    it('should reject duplicate email', async () => {
      await request(app)
        .post('/users')
        .send({ email: 'john@example.com', name: 'John Doe' });

      const res = await request(app)
        .post('/users')
        .send({ email: 'john@example.com', name: 'Jane Doe' });

      expect(res.status).toBe(409);
      expect(res.body.type).toContain('conflict');
    });

    it('should reject missing email', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: 'John Doe' });

      expect(res.status).toBe(422);
    });

    it('should reject missing name', async () => {
      const res = await request(app)
        .post('/users')
        .send({ email: 'john@example.com' });

      expect(res.status).toBe(422);
    });
  });

  describe('GET /users/:id', () => {
    it('should get a user by id', async () => {
      const createRes = await request(app)
        .post('/users')
        .send({ email: 'john@example.com', name: 'John Doe' });

      const userId = createRes.body.id;

      const res = await request(app).get(`/users/${userId}`);

      expect(res.status).toBe(200);
      expect(res.body.id).toBe(userId);
      expect(res.body.email).toBe('john@example.com');
      expect(res.body.name).toBe('John Doe');
    });

    it('should return 404 for unknown user', async () => {
      const res = await request(app).get('/users/00000000-0000-0000-0000-000000000000');

      expect(res.status).toBe(404);
      expect(res.body.type).toContain('not-found');
    });

    it('should reject invalid uuid', async () => {
      const res = await request(app).get('/users/not-a-uuid');

      expect(res.status).toBe(422);
    });
  });

  describe('GET /users', () => {
    it('should list users with default limit', async () => {
      await request(app)
        .post('/users')
        .send({ email: 'user1@example.com', name: 'User 1' });

      await request(app)
        .post('/users')
        .send({ email: 'user2@example.com', name: 'User 2' });

      const res = await request(app).get('/users');

      expect(res.status).toBe(200);
      expect(res.body.data).toHaveLength(2);
      expect(res.body.nextCursor).toBeNull();
    });

    it('should list users with custom limit', async () => {
      for (let i = 1; i <= 5; i++) {
        await request(app)
          .post('/users')
          .send({ email: `user${i}@example.com`, name: `User ${i}` });
      }

      const res = await request(app).get('/users?limit=2');

      expect(res.status).toBe(200);
      expect(res.body.data).toHaveLength(2);
      expect(res.body.nextCursor).toBeTruthy();
    });

    it('should reject limit > 100', async () => {
      const res = await request(app).get('/users?limit=101');

      expect(res.status).toBe(422);
    });

    it('should use cursor pagination', async () => {
      for (let i = 1; i <= 5; i++) {
        await request(app)
          .post('/users')
          .send({ email: `user${i}@example.com`, name: `User ${i}` });
      }

      const page1 = await request(app).get('/users?limit=2');
      expect(page1.body.data).toHaveLength(2);
      expect(page1.body.nextCursor).toBeTruthy();

      const page2 = await request(app).get(`/users?limit=2&cursor=${page1.body.nextCursor}`);
      expect(page2.body.data).toHaveLength(2);
    });

    it('should reject invalid cursor', async () => {
      const res = await request(app).get('/users?cursor=invalid');

      expect(res.status).toBe(422);
    });
  });

  describe('PATCH /users/:id', () => {
    it('should update user email', async () => {
      const createRes = await request(app)
        .post('/users')
        .send({ email: 'john@example.com', name: 'John Doe' });

      const userId = createRes.body.id;

      const res = await request(app)
        .patch(`/users/${userId}`)
        .send({ email: 'newemail@example.com' });

      expect(res.status).toBe(200);
      expect(res.body.email).toBe('newemail@example.com');
      expect(res.body.name).toBe('John Doe');
    });

    it('should update user name', async () => {
      const createRes = await request(app)
        .post('/users')
        .send({ email: 'john@example.com', name: 'John Doe' });

      const userId = createRes.body.id;

      const res = await request(app)
        .patch(`/users/${userId}`)
        .send({ name: 'Jane Doe' });

      expect(res.status).toBe(200);
      expect(res.body.email).toBe('john@example.com');
      expect(res.body.name).toBe('Jane Doe');
    });

    it('should update both email and name', async () => {
      const createRes = await request(app)
        .post('/users')
        .send({ email: 'john@example.com', name: 'John Doe' });

      const userId = createRes.body.id;

      const res = await request(app)
        .patch(`/users/${userId}`)
        .send({ email: 'newemail@example.com', name: 'New Name' });

      expect(res.status).toBe(200);
      expect(res.body.email).toBe('newemail@example.com');
      expect(res.body.name).toBe('New Name');
    });

    it('should reject invalid email in patch', async () => {
      const createRes = await request(app)
        .post('/users')
        .send({ email: 'john@example.com', name: 'John Doe' });

      const userId = createRes.body.id;

      const res = await request(app)
        .patch(`/users/${userId}`)
        .send({ email: 'not-an-email' });

      expect(res.status).toBe(422);
    });

    it('should reject invalid name in patch', async () => {
      const createRes = await request(app)
        .post('/users')
        .send({ email: 'john@example.com', name: 'John Doe' });

      const userId = createRes.body.id;

      const res = await request(app)
        .patch(`/users/${userId}`)
        .send({ name: '' });

      expect(res.status).toBe(422);
    });

    it('should reject duplicate email in patch', async () => {
      const createRes1 = await request(app)
        .post('/users')
        .send({ email: 'user1@example.com', name: 'User 1' });

      const createRes2 = await request(app)
        .post('/users')
        .send({ email: 'user2@example.com', name: 'User 2' });

      const userId2 = createRes2.body.id;

      const res = await request(app)
        .patch(`/users/${userId2}`)
        .send({ email: 'user1@example.com' });

      expect(res.status).toBe(409);
    });

    it('should return 404 for unknown user in patch', async () => {
      const res = await request(app)
        .patch('/users/00000000-0000-0000-0000-000000000000')
        .send({ name: 'New Name' });

      expect(res.status).toBe(404);
    });

    it('should reject invalid uuid in patch', async () => {
      const res = await request(app)
        .patch('/users/not-a-uuid')
        .send({ name: 'New Name' });

      expect(res.status).toBe(422);
    });
  });

  describe('DELETE /users/:id', () => {
    it('should delete a user', async () => {
      const createRes = await request(app)
        .post('/users')
        .send({ email: 'john@example.com', name: 'John Doe' });

      const userId = createRes.body.id;

      const deleteRes = await request(app).delete(`/users/${userId}`);
      expect(deleteRes.status).toBe(204);

      const getRes = await request(app).get(`/users/${userId}`);
      expect(getRes.status).toBe(404);
    });

    it('should return 404 when deleting unknown user', async () => {
      const res = await request(app).delete('/users/00000000-0000-0000-0000-000000000000');

      expect(res.status).toBe(404);
    });

    it('should reject invalid uuid in delete', async () => {
      const res = await request(app).delete('/users/not-a-uuid');

      expect(res.status).toBe(422);
    });
  });
});

import { z } from 'zod';

// User schema with required email and name, optional server-generated id and createdAt

export const User = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  name: z.string().min(1).max(100),
  createdAt: z.string().datetime(),
});

export type User = z.infer<typeof User>;

export const CreateUserInput = z.strictObject({
  email: z.string().email(),
  name: z.string().min(1).max(100),
});

export type CreateUserInput = z.infer<typeof CreateUserInput>;

export const UpdateUserInput = z.strictObject({
  email: z.string().email().optional(),
  name: z.string().min(1).max(100).optional(),
});

export type UpdateUserInput = z.infer<typeof UpdateUserInput>;

