      const data = {
        email: 'test@example.com',
        name: 'Test User',
      };
      expect(() => CreateUserInput.parse(data)).not.toThrow();
    });

    it('should reject invalid email', () => {
      const data = {
        email: 'not-an-email',
        name: 'Test User',
      };
      expect(() => CreateUserInput.parse(data)).toThrow();
    });

    it('should reject name with length 0', () => {
      const data = {
        email: 'test@example.com',
        name: '',
      };
      expect(() => CreateUserInput.parse(data)).toThrow();
    });

    it('should reject name with length > 100', () => {
      const data = {
        email: 'test@example.com',
        name: 'a'.repeat(101),
      };
      expect(() => CreateUserInput.parse(data)).toThrow();
    });

    it('should reject missing email', () => {
      const data = {
        name: 'Test User',
      };
      expect(() => CreateUserInput.parse(data)).toThrow();
    });

    it('should reject missing name', () => {
      const data = {
        email: 'test@example.com',
      };
      expect(() => CreateUserInput.parse(data)).toThrow();
    });

    it('should reject extra fields', () => {
      const data = {
        email: 'test@example.com',
        name: 'Test User',
        extra: 'field',
      };
      expect(() => CreateUserInput.parse(data)).toThrow();
    });
  });

  describe('UpdateUserInput', () => {
    it('should parse valid input with email only', () => {
      const data = {
        email: 'test@example.com',
      };
      expect(() => UpdateUserInput.parse(data)).not.toThrow();
    });

    it('should parse valid input with name only', () => {
      const data = {
        name: 'Test User',
      };
      expect(() => UpdateUserInput.parse(data)).not.toThrow();
    });

    it('should parse valid input with both', () => {
      const data = {
        email: 'test@example.com',
        name: 'Test User',
