import { z } from 'zod';
import { v4 as uuidv4 } from 'uuid';

export const UserSchema = z.object({
  id: z.string().uuid().optional().default(uuidv4),
  email: z.string().email(),
  name: z.string().min(1).max(100),
  createdAt: z.date().optional().default(() => new Date()),
});

export type User = z.infer<typeof UserSchema>;

export const CreateUserSchema = UserSchema.pick({ email: true, name: true });
export type CreateUser = z.infer<typeof CreateUserSchema>;

export const UpdateUserSchema = UserSchema.pick({ email: true, name: true }).partial();
export type UpdateUser = z.infer<typeof UpdateUserSchema>;

import { Router } from 'express';
import { v4 as uuidv4 } from 'uuid';
import { userSchema } from '../schemas/user';
import * as store from '../http/store';
import * as problem from '../http/problem';
import * as pagination from '../http/pagination';

const users = new Map<string, any>();

export const router = Router();

// POST /users - Create a user
router.post('/', (req, res) => {
  try {
    const { email, name } = req.body;

    // Validate input
    const parsed = userSchema.create.safeParse({ email, name });
    if (!parsed.success) {
      return res.status(422).json(problem.invalid(parsed.error));
    }

    // Check for duplicate email
    for (const user of users.values()) {
      if (user.email === email) {
        return res.status(409).json(problem.conflict('Email already exists'));
      }
    }

    // Create user
    const id = uuidv4();
    const user = {
      id,
      email,
      name,
      createdAt: new Date().toISOString()
    };
    users.set(id, user);

    res.status(201).json(user);
  } catch (err) {
    res.status(500).json(problem.internal());
  }
});

// GET /users/:id - Get a user by id
router.get('/:id', (req, res) => {
  try {
    const { id } = req.params;
    const user = users.get(id);

    if (!user) {
      return res.status(404).json(problem.notFound());
    }

    res.json(user);
  } catch (err) {
    res.status(500).json(problem.internal());
  }
});

// GET /users - List users with cursor pagination
router.get('/', (req, res) => {
  try {
    const { limit = '20', cursor } = req.query;
    const parsedLimit = parseInt(limit as string);

    if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
      return res.status(422).json(problem.invalid());
    }

    const usersList = Array.from(users.values()).sort((a, b) => 
      new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
    );

    let startIndex = 0;
    if (cursor) {
      startIndex = usersList.findIndex(u => u.id === cursor) + 1;
      if (startIndex === 0) {
        return res.status(400).json(problem.invalid());
      }
    }

    const items = usersList.slice(startIndex, startIndex + parsedLimit);
    const nextCursor = items.length === parsedLimit ? items[items.length - 1].id : null;

    res.json({
      items,
      nextCursor
    });
  } catch (err) {
    res.status(500).json(problem.internal());
  }
});

// PATCH /users/:id - Partially update a user
router.patch('/:id', (req, res) => {
  try {
    const { id } = req.params;
    const user = users.get(id);

    if (!user) {
      return res.status(404).json(problem.notFound());
    }

    const { email, name } = req.body;

    // Validate if provided
    if (email !== undefined || name !== undefined) {
      const updateData: any = {};
      if (email !== undefined) updateData.email = email;
      if (name !== undefined) updateData.name = name;

      const parsed = userSchema.patch.safeParse(updateData);
      if (!parsed.success) {
        return res.status(422).json(problem.invalid(parsed.error));
      }
    }

    // Check for duplicate email if updating email
    if (email !== undefined && email !== user.email) {
      for (const u of users.values()) {
        if (u.email === email) {
          return res.status(409).json(problem.conflict('Email already exists'));
        }
      }
      user.email = email;
    }

    if (name !== undefined) {
      user.name = name;
    }

    users.set(id, user);
    res.json(user);
  } catch (err) {
    res.status(500).json(problem.internal());
  }
});

// DELETE /users/:id - Delete a user
router.delete('/:id', (req, res) => {
  try {
    const { id } = req.params;
    const user = users.get(id);

    if (!user) {
      return res.status(404).json(problem.notFound());
    }

    users.delete(id);
    res.status(204).send();
  } catch (err) {
    res.status(500).json(problem.internal());
  }
});
